import { isOmpExecutable, isOpenCodeExecutable, optionValue, parseOpenCodeArgv, preflightArgvDispatch, scratchSessionRoot } from "./ufo-sighting-lib/argv.mjs";
import { levelStatus, loadObservations, observeMissionTasks, sparkStateRoot, statusPhase } from "./ufo-sighting-lib/observe.mjs";
import { DEFAULT_PEEK_LINES, MAX_PEEK_LINES, output, requireNoArgs, runLegacyNativeDirect, surfaceManifest, usage, usageForVerb } from "./ufo-sighting-lib/surface.mjs";

function validateStoredEnvironment(value, { filesystem = false } = {}) {
  assertEnvironmentObject(value, "mission environment");
  assertExactKeys(value, ["schema", "ephemeralRoot", "environment", "envFile"], "mission environment");
  if (value.schema !== EPHEMERAL_POLICY.environmentSchema) environmentFail("environment schema is unsupported");
  if (typeof value.ephemeralRoot !== "string" || !path.isAbsolute(value.ephemeralRoot)
    || path.resolve(value.ephemeralRoot) !== value.ephemeralRoot || value.ephemeralRoot.includes("\0")) {
    environmentFail("ephemeral root must be an absolute canonical path");
  }
  if (typeof value.envFile !== "string" || !path.isAbsolute(value.envFile)
    || path.resolve(value.envFile) !== value.envFile || !beneath(value.ephemeralRoot, value.envFile)) {
    environmentFail("environment file must be beneath the declared ephemeral root");
  }
  assertEnvironmentObject(value.environment, "environment variables");
  const flagKeys = Object.keys(EPHEMERAL_POLICY.flagVariables);
  assertExactKeys(value.environment, [...EPHEMERAL_POLICY.pathVariables, ...flagKeys], "environment variables");
  for (const key of EPHEMERAL_POLICY.pathVariables) {
    const candidate = value.environment[key];
    if (typeof candidate !== "string" || !path.isAbsolute(candidate) || path.resolve(candidate) !== candidate
      || candidate.includes("\0") || !beneath(value.ephemeralRoot, candidate)) {
      environmentFail(`${key} must be an absolute path beneath the declared ephemeral root`);
    }
  }
  for (const [key, expected] of Object.entries(EPHEMERAL_POLICY.flagVariables)) {
    if (value.environment[key] !== expected) environmentFail(`${key} must equal ${expected}`);
  }
  if (!filesystem) return value;

  let rootInfo;
  try {
    rootInfo = lstatSync(value.ephemeralRoot);
  } catch {
    environmentFail("ephemeral root is missing");
  }
  if (rootInfo.isSymbolicLink()) environmentFail("ephemeral root must not be a symlink");
  assertPrivateOwned(rootInfo, "ephemeral root", "directory");
  if (realpathSync(value.ephemeralRoot) !== value.ephemeralRoot) environmentFail("ephemeral root must be canonical");
  for (const key of EPHEMERAL_POLICY.pathVariables) {
    const candidate = value.environment[key];
    if (key === "OPENCODE_DB") {
      assertRealPrivateDirectoryChain(value.ephemeralRoot, path.dirname(candidate), key);
      if (existsSync(candidate)) {
        const info = lstatSync(candidate);
        if (info.isSymbolicLink()) environmentFail("OPENCODE_DB must not be a symlink");
        assertPrivateOwned(info, "OPENCODE_DB", "file");
      }
    } else {
      assertRealPrivateDirectoryChain(value.ephemeralRoot, candidate, key);
    }
  }
  return value;
}

export function loadMissionEnvironment(envFile, { allowedMarkerStates = ["prepared"] } = {}) {
  if (typeof envFile !== "string" || !path.isAbsolute(envFile) || path.resolve(envFile) !== envFile) {
    environmentFail("environment file path must be absolute and canonical");
  }
  let info;
  try {
    info = lstatSync(envFile);
  } catch {
    environmentFail("environment file is missing");
  }
  if (info.isSymbolicLink()) environmentFail("environment file must not be a symlink");
  assertPrivateOwned(info, "environment file", "file");
  if (info.size < 2 || info.size > EPHEMERAL_POLICY.maxEnvironmentBytes) {
    environmentFail("environment file size is outside the policy bound");
  }
  let parsed;
  try {
    // Post-read bound closes the lstat→read grow race on the env file.
    parsed = JSON.parse(readBoundedUtf8(envFile, EPHEMERAL_POLICY.maxEnvironmentBytes));
  } catch (error) {
    // A SightingError from readBoundedUtf8 (grow-race bound trip, fs fault)
    // is already typed — retyping it as "not valid JSON" would misreport the
    // cause, the same distinction the marker read below keeps.
    if (error instanceof SightingError) throw error;
    environmentFail("environment file is not valid JSON");
  }
  assertEnvironmentObject(parsed, "environment file");
  assertExactKeys(parsed, ["schema", "ephemeralRoot", "environment"], "environment file");
  const stored = validateStoredEnvironment({ ...parsed, envFile }, { filesystem: true });
  assertRealPrivateDirectoryChain(stored.ephemeralRoot, path.dirname(envFile), "environment file");
  if (realpathSync(envFile) !== envFile) environmentFail("environment file must be canonical");
  const markerPath = path.join(stored.ephemeralRoot, EPHEMERAL_POLICY.marker);
  let marker;
  try {
    const markerInfo = lstatSync(markerPath);
    if (markerInfo.isSymbolicLink()) environmentFail("ephemeral marker must not be a symlink");
    assertPrivateOwned(markerInfo, "ephemeral marker", "file");
    if (markerInfo.size > EPHEMERAL_POLICY.maxEnvironmentBytes) environmentFail("ephemeral marker exceeds the policy byte bound");
    marker = JSON.parse(readBoundedUtf8(markerPath, EPHEMERAL_POLICY.maxEnvironmentBytes));
  } catch (error) {
    if (error instanceof SightingError) throw error;
    environmentFail("ephemeral marker is missing or malformed");
  }
  if (marker?.schema !== EPHEMERAL_POLICY.markerSchema
    || marker.root !== stored.ephemeralRoot
    || marker.envFile !== envFile
    || !Array.isArray(marker.activePids)
    || marker.activePids.length !== 0
    || !allowedMarkerStates.includes(marker.state)) {
    environmentFail("ephemeral marker does not attest the required inactive root state");
  }
  return stored;
}

function validateDispatch(value) {
  assertPlainObject(value, "dispatch");
  if (value.kind === "inquiry") {
    assertSafeText(value.slug, "inquiry slug", 128);
    if (typeof value.promptPath !== "string" || !path.isAbsolute(value.promptPath) || value.promptPath.includes("\0")) {
      fail("INVALID_DISPATCH", "inquiry prompt path must be absolute");
    }
    if (typeof value.sessionDir !== "string" || !path.isAbsolute(value.sessionDir) || value.sessionDir.includes("\0")) {
      fail("INVALID_DISPATCH", "inquiry session directory must be absolute");
    }
    return value;
  }
  if (value.kind === "native-trial") {
    validateArgv(value.args);
    return value;
  }
  if (value.kind === "argv") {
    validateArgv(value.argv);
    return value;
  }
  fail("INVALID_DISPATCH", `unsupported dispatch kind: ${String(value.kind)}`);
}

function validateProvenance(value) {
  assertPlainObject(value, "provenance");
  if (value.twinDepth !== 0 && value.twinDepth !== 1) fail("MALFORMED_MANIFEST", "twin depth must be 0 or 1");
  if (value.originMissionId !== null) validateMissionId(value.originMissionId);
  if (value.originRunId !== null) validateRunId(value.originRunId);
  if (value.originSessionId !== null) validateSessionId(value.originSessionId);
  validateMissionId(value.ownerMissionId);
  return value;
}

const MAX_STOPPED_MISSIONS = 100;

function pruneStoppedMissions(state) {
  const stopped = state.missions.filter((m) => m.status === "stopped");
  if (stopped.length <= MAX_STOPPED_MISSIONS) return;
  const evictIds = new Set(
    sortMissions(stopped).slice(0, stopped.length - MAX_STOPPED_MISSIONS).map((m) => m.id),
  );
  state.missions = state.missions.filter((m) => !evictIds.has(m.id));
}

function validateMission(value) {
  assertPlainObject(value, "mission");
  validateMissionId(value.id);
  if (!Number.isSafeInteger(value.sequence) || value.sequence < 1) fail("MALFORMED_MANIFEST", "mission sequence is invalid");
  validateRunId(value.runId, { native: value.dispatch?.kind === "native-trial" });
  validateSessionId(value.sessionId);
  assertSafeText(value.title, "mission title", 64);
  assertSafeText(value.substrate, "mission substrate", 32);
  if (value.paneId !== null && (typeof value.paneId !== "string" || !/^%\d+$/u.test(value.paneId))) {
    fail("MALFORMED_MANIFEST", "mission pane id is invalid");
  }
  // panePid binds the pane's process identity at spawn time; pane markers
  // survive respawn-pane, so the pid is the only evidence that the marked
  // pane still runs the mission's own wrapper. Optional: legacy rows lack it.
  if (value.panePid !== undefined && value.panePid !== null
    && (!Number.isSafeInteger(value.panePid) || value.panePid < 1)) {
    fail("MALFORMED_MANIFEST", "mission pane pid is invalid");
  }
  if (typeof value.cwd !== "string" || !path.isAbsolute(value.cwd) || value.cwd.includes("\0")) {
    fail("MALFORMED_MANIFEST", "mission cwd must be absolute");
  }
  if (value.status !== "starting" && value.status !== "running" && value.status !== "completed" && value.status !== "stopped") {
    fail("MALFORMED_MANIFEST", "mission status is invalid");
  }
  if (value.runnerReservation === undefined) {
    value.runnerReservation = value.status === "completed" ? 0 : 1;
  } else if (!Number.isSafeInteger(value.runnerReservation) || value.runnerReservation < 0) {
    fail("MALFORMED_MANIFEST", "mission runner reservation is invalid");
  } else if (value.status !== "completed" && value.runnerReservation < 1) {
    fail("MALFORMED_MANIFEST", "active mission runner reservation must be positive");
  }
  if (value.status === "completed") {
    if (typeof value.completedAt !== "string" || Number.isNaN(Date.parse(value.completedAt))) {
      fail("MALFORMED_MANIFEST", "completed mission must have a valid completedAt timestamp");
    }
    if (value.finalNote !== null && value.finalNote !== undefined && typeof value.finalNote !== "string") {
      fail("MALFORMED_MANIFEST", "finalNote must be a string");
    }
    if (value.completedCapture !== undefined && value.completedCapture !== null && typeof value.completedCapture !== "string") {
      fail("MALFORMED_MANIFEST", "completedCapture must be a string");
    }
  }
  if (value.status === "stopped") {
    if (typeof value.stoppedAt !== "string" || Number.isNaN(Date.parse(value.stoppedAt))) {
      fail("MALFORMED_MANIFEST", "stopped mission must have a valid stoppedAt timestamp");
    }
    // Normalize absent outcome fields to null so the late-stop backfill in
    // stopMission (which keys on === null) also covers legacy rows.
    if (value.exitCode === undefined) value.exitCode = null;
    if (value.exitSignal === undefined) value.exitSignal = null;
    if (value.exitCode !== null && !Number.isSafeInteger(value.exitCode)) {
      fail("MALFORMED_MANIFEST", "stopped exitCode must be an integer or null");
    }
    if (value.exitSignal !== null && (typeof value.exitSignal !== "string" || value.exitSignal.includes("\0"))) {
      fail("MALFORMED_MANIFEST", "stopped exitSignal must be a string or null");
    }
  }
  // S-10: relay is an operator-supplied display label, not an authenticated
  // origin. It marks missions dispatched from the operator surface (L0) but
  // carries no cryptographic attestation. Downstream consumers MUST NOT treat
  // it as a security boundary or authorization token.
  if (value.relay !== undefined && typeof value.relay !== "boolean") fail("MALFORMED_MANIFEST", "mission relay flag must be a boolean");
  if (value.fleet == null || value.fleet === "") {
    value.fleet = null;
  } else if (typeof value.fleet !== "string" || !FLEET_NAME_PATTERN.test(value.fleet)) {
    fail("MALFORMED_MANIFEST", "mission fleet is invalid");
  }
  validateDispatch(value.dispatch);
  if (value.environment !== undefined) validateStoredEnvironment(value.environment);
  validateProvenance(value.provenance);
  validateRetentionRecord(value.retention);
  if (value.twinMissionId !== null) validateMissionId(value.twinMissionId);
  if (value.steerCount !== undefined) {
    if (!Number.isSafeInteger(value.steerCount) || value.steerCount < 0) {
      fail("MALFORMED_MANIFEST", "mission steerCount must be a non-negative integer");
    }
  }
  if (value.lastSteerAt !== undefined) {
    if (typeof value.lastSteerAt !== "string" || Number.isNaN(Date.parse(value.lastSteerAt))) {
      fail("MALFORMED_MANIFEST", "mission lastSteerAt must be a valid timestamp");
    }
  }
  if (value.lastSteerBytes !== undefined) {
    if (!Number.isSafeInteger(value.lastSteerBytes) || value.lastSteerBytes < 0) {
      fail("MALFORMED_MANIFEST", "mission lastSteerBytes must be a non-negative integer");
    }
  }
  return value;

}

function normalizeRegistryRevision(value) {
  if (value === undefined) return 0;
  if (!Number.isSafeInteger(value) || value < 0) fail("MALFORMED_MANIFEST", "registry revision is invalid");
  return value;
}

export function validateManifest(value) {
  assertPlainObject(value, "manifest");
  if (value.schema !== MANIFEST_SCHEMA) fail("MALFORMED_MANIFEST", "manifest schema is unsupported");
  if (typeof value.wallId !== "string" || !/^[a-f0-9-]{36}$/u.test(value.wallId)) {
    fail("MALFORMED_MANIFEST", "wall id is invalid");
  }
  if (value.ownerRoot !== ROOT || value.target !== TMUX_TARGET) fail("FOREIGN_STATE", "manifest belongs to another wall");
  if (!Number.isSafeInteger(value.nextSequence) || value.nextSequence < 1) fail("MALFORMED_MANIFEST", "next sequence is invalid");
  value.registryRevision = normalizeRegistryRevision(value.registryRevision);
  if (value.profile !== "16:9" && value.profile !== "21:9") fail("MALFORMED_MANIFEST", "profile is invalid");
  if (!Array.isArray(value.missions)) fail("MALFORMED_MANIFEST", "missions must be an array");
  value.missions.forEach(validateMission);
  const unique = (items, label) => {
    if (new Set(items).size !== items.length) fail("MALFORMED_MANIFEST", `${label} must be unique`);
  };
  unique(value.missions.map(({ id }) => id), "mission ids");
  unique(value.missions.map(({ runId }) => runId), "run ids");
  unique(value.missions.map(({ sessionId }) => sessionId), "session ids");
  unique(value.missions.filter(({ paneId, status }) => paneId && isLiveStatus(status)).map(({ paneId }) => paneId), "pane ids");
  // Sequence order is the launch/eviction order; duplicates are unrecoverable
  // ambiguity, while a lagging nextSequence is repairable drift — normalize it
  // forward like the other migration defaults.
  unique(value.missions.map(({ sequence }) => sequence), "mission sequences");
  const maxSequence = value.missions.reduce((max, mission) => Math.max(max, mission.sequence), 0);
  if (value.nextSequence <= maxSequence) value.nextSequence = maxSequence + 1;
  if (value.terminal !== null) {
    assertPlainObject(value.terminal, "terminal");
    // Fields mirror what resolveTerminalOnce persists: a malformed terminal
    // must fail typed here, not as a TypeError in terminalPidFromAncestor.
    if (typeof value.terminal.desktopId !== "string" || !/^[A-Za-z0-9._-]{1,256}$/u.test(value.terminal.desktopId)) {
      fail("MALFORMED_MANIFEST", "terminal desktop id is invalid");
    }
    if (!Array.isArray(value.terminal.command) || value.terminal.command.length < 1
      || value.terminal.command.length > 16
      || value.terminal.command.some((arg) => typeof arg !== "string" || arg.length === 0 || arg.length > 1024 || arg.includes("\0"))) {
      fail("MALFORMED_MANIFEST", "terminal command is invalid");
    }
    if (value.terminal.pid === undefined) value.terminal.pid = null;
    if (value.terminal.pid !== null && (!Number.isSafeInteger(value.terminal.pid) || value.terminal.pid < 1)) {
      fail("MALFORMED_MANIFEST", "terminal pid is invalid");
    }
  }
  if (value.geometry !== null) assertPlainObject(value.geometry, "geometry");
  return value;
}

