import re

def source_text(rev,path):
    return subprocess.check_output(['git','show',f'{rev}:{path}'],cwd=root,text=True)

def source_measure(rev):
    paths=subprocess.check_output(['git','ls-tree','-r','--name-only',rev,'--','corpus/knowledge'],cwd=root,text=True).splitlines()
    files={pathlib.PurePosixPath(p).stem for p in paths if p.endswith('.md')}
    section=source_text(rev,'corpus/README.md').split('## Coverage map\n',1)[1].split('\n## ',1)[0]
    mapped=set(re.findall(r'2026-10-\d{2}-[a-z0-9-]+',section))
    craft=source_text(rev,'SKILL.md').split('## Queue-drain craft ',1)[1].split('\n## ',1)[0]
    rules=re.split(r'(?m)^- \*\*',craft)[1:]
    resolved=0
    for rule in rules:
        refs=re.findall(r'corpus/knowledge/([a-z0-9-]+\.md)(?::(\d+)(?:-(\d+))?)?',rule)
        valid=bool(refs)
        for name,first,last in refs:
            try:
                count=len(source_text(rev,'corpus/knowledge/'+name).splitlines())
                valid=valid and 1<=int(first or 1)<=int(last or first or 1)<=count
            except subprocess.CalledProcessError:
                valid=False
        resolved+=valid
